    }

    // ─── Legacy / Local login (kept for offline/demo fallback) ─

    fun login(phone: String, name: String = "") {
        _isLoggedIn.value = true
        _phone.value = phone
        if (name.isNotBlank()) _parentName.value = name
    }

    fun completeOnboarding() {
        _onboardingComplete.value = true
    }

