        }
        _sessionToken.value = null
        ApiService.clearSession()
        SecureTokenStore.clear(app)
        _isLoggedIn.value = false
        _onboardingComplete.value = false
        _userId.value = ""
        _email.value = ""
        _phone.value = ""
