        SecureTokenStore.clear(app)
        _isLoggedIn.value = false
        _userId.value = ""
    }

    fun clearAuthError() { _authError.value = null }
    fun clearAuthLoading() { _authLoading.value = false }
    fun setOnboardingComplete(v: Boolean) { _onboardingComplete.value = v }
}

