                isLoading = authLoading,
                authError = authError,
                onSignInWithGoogle = { onGoogleSignInRequest() },
                onContinueWithPhone = { p ->
                    phone = p
                    pendingName = "Parent"
                    appViewModel.sendPhoneOtp(p)
                    navController.navigate("otp/$p/$pendingName")
                },
            )
